package dev.jackteng.encore;
import com.fasterxml.jackson.databind.ObjectMapper;import dev.jackteng.encore.admission.AdmissionSettings;import dev.jackteng.encore.catalog.*;import dev.jackteng.encore.catalog.Models.*;import dev.jackteng.encore.customer.CustomerService;import dev.jackteng.encore.orders.*;import dev.jackteng.encore.orders.OrderModels.*;import dev.jackteng.encore.inventory.*;import dev.jackteng.encore.common.ApiErrors.Problem;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.expiry.enabled=false","ticket.stock-recovery.enabled=false","ticket.stock-review.enabled=true","ticket.stock-maintenance.enabled=true"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockReviewIntegrationTest {
 @org.springframework.test.context.bean.override.mockito.MockitoSpyBean JdbcTemplate db;@Autowired StringRedisTemplate redis;@Autowired ObjectMapper json;@Autowired AdmissionSettings settings;@Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired PurchaseService purchases;@Autowired StockProjectionService projections;@Autowired StockHoldService holds;@Autowired StockSettlementService settlement;@Autowired StockRecoveryStore recovery;@Autowired StockRecoveryWorker worker;@Autowired StockReviewService reviews;@Autowired StockMaintenanceService maintenance;@Autowired PlatformTransactionManager transactions;
 String manager="review-"+UUID.randomUUID();RedisTicketLedger ledger;Set<String> ownKeys=new HashSet<>();
 record Case(UUID ticket,UUID intent,String kind,String target,Map<Object,Object> backup){}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));ledger=RedisTicketLedger.epochs(redis,json,settings.namespace());db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"synthetic unused hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(ownKeys);ownKeys.clear();}
 UUID ticket(){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"review-"+UUID.randomUUID(),"合成核對","不售票","隔離"));var now=OffsetDateTime.now();var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成",now.plusDays(2),now.minusHours(1),now.plusHours(2)));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般",1200,4,4));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);var c=projections.begin(t.id(),UUID.randomUUID(),1);ownKeys.add(ledger.key(t.id(),1));assertEquals("READY",projections.complete(c.requestId()).state());return t.id();}
 Case review(String target){UUID t=ticket();var user=customers.register("r-"+UUID.randomUUID(),"合成",UUID.randomUUID().toString());var who=customers.authenticate(user.token()).orElseThrow();var h=holds.prepare(who,new Place(UUID.randomUUID(),t,1,1,1200));holds.apply(h.id());String kind=target.equals("ABANDON")?"UNUSED":"SETTLEMENT";
  if(kind.equals("SETTLEMENT")){var p=purchases.acceptHold(who,h.id());if(target.equals("COMMIT"))purchases.process(db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id()));else purchases.cancel(who,p.id(),new Cancel(UUID.randomUUID(),1));}
  var backup=new HashMap<>(redis.opsForHash().entries(ledger.key(t,1)));redis.delete(ledger.key(t,1));redis.opsForValue().set(ledger.key(t,1),"synthetic-corrupt");if(kind.equals("UNUSED"))holds.abandon(h.id());boolean found=false;for(int n=0;n<1000;n++){var claim=recovery.claim(30);if(claim.isEmpty())break;worker.run(claim.get());if(claim.get().intentId().equals(h.id())&&claim.get().kind().equals(kind)){found=true;break;}}assertTrue(found);assertEquals("REVIEW",db.queryForObject("SELECT state FROM stock_recovery_job WHERE intent_id=? AND kind=?",String.class,h.id(),kind));return new Case(t,h.id(),kind,target,backup);
 }
 void restore(Case c){redis.delete(ledger.key(c.ticket(),1));redis.opsForHash().putAll(ledger.key(c.ticket(),1),c.backup());}
 StockReviewService.Begin body(Case c){return new StockReviewService.Begin(UUID.randomUUID(),c.kind(),1,c.target());}
 int audits(UUID id){return db.queryForObject("SELECT count(*) FROM stock_review_audit WHERE request_id=?",Integer.class,id);}
 String job(Case c){return db.queryForObject("SELECT to_jsonb(j)::text FROM stock_recovery_job j WHERE intent_id=? AND kind=?",String.class,c.intent(),c.kind());}
 void problem(String code,Runnable op){assertEquals(code,assertThrows(Problem.class,op::run).code);}
 String other(String role){String s="staff-"+UUID.randomUUID();db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),s,"synthetic unused hash",role);return s;}
 @Test void committedUnusedPeerBetweenRegistrationAndValidationReplaysOriginal()throws Exception{committedPeerReplay("ABANDON");}
 @Test void committedSettlementPeerBetweenRegistrationAndValidationReplaysOriginal()throws Exception{committedPeerReplay("COMMIT");}
 void committedPeerReplay(String target)throws Exception {
  var c=review(target);restore(c);var b=body(c);String before=job(c);
  var paused=new CountDownLatch(1);var peerFinished=new CountDownLatch(1);
  String query="SELECT state,attempts FROM stock_recovery_job WHERE intent_id=? AND kind=?";
  org.mockito.Mockito.doAnswer(invocation->{if(Thread.currentThread().getName().equals("delayed-review-register")){paused.countDown();assertTrue(peerFinished.await(5,TimeUnit.SECONDS));}return invocation.callRealMethod();})
   .when(db).queryForList(org.mockito.ArgumentMatchers.eq(query),org.mockito.ArgumentMatchers.eq(c.intent()),org.mockito.ArgumentMatchers.eq(c.kind()));
  try(var pool=Executors.newSingleThreadExecutor(job->new Thread(job,"delayed-review-register"))){
   var delayed=pool.submit(()->reviews.submit(manager,c.intent(),b));
   try{assertTrue(paused.await(5,TimeUnit.SECONDS));assertEquals("RESOLVED",reviews.submit(manager,c.intent(),b).state());}
   finally{peerFinished.countDown();}
   assertEquals("RESOLVED",delayed.get().state());
  }finally{org.mockito.Mockito.doCallRealMethod().when(db).queryForList(org.mockito.ArgumentMatchers.eq(query),org.mockito.ArgumentMatchers.eq(c.intent()),org.mockito.ArgumentMatchers.eq(c.kind()));}
  assertEquals(before,job(c));assertEquals(target.equals("ABANDON")?2:3,audits(b.requestId()));
  assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_review_command WHERE request_id=?",Integer.class,b.requestId()));
  assertEquals(target.equals("ABANDON")?0:1,db.queryForObject("SELECT count(*) FROM ticket_order WHERE ticket_id=?",Integer.class,c.ticket()));
 }
 @Test void unusedResolvesOriginalAbandonmentAndKeepsReviewBudget(){var c=review("ABANDON");String before=job(c);restore(c);var r=reviews.submit(manager,c.intent(),body(c));assertEquals("RESOLVED",r.state());assertEquals("RELEASED",r.resolution());assertEquals("ABORTED",r.currentIntentState());assertEquals(2,audits(r.requestId()));assertEquals(before,job(c));assertEquals(4,ledger.snapshot(c.ticket(),1).snapshot().available());assertEquals(0,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,c.ticket()));assertEquals("DIRTY",projections.inspect(c.ticket()).state());}
 @Test void formalCommitUsesImmutablePgDecisionWithoutNewOrder(){var c=review("COMMIT");String before=job(c);restore(c);var r=reviews.submit(manager,c.intent(),body(c));assertEquals("RESOLVED",r.state());assertEquals("COMMITTED",r.resolution());assertEquals(3,audits(r.requestId()));assertEquals(before,job(c));assertEquals(1,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,c.ticket()));assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_hold_ack WHERE intent_id=?",Integer.class,c.intent()));assertEquals(1,db.queryForObject("SELECT count(*) FROM ticket_order WHERE ticket_id=?",Integer.class,c.ticket()));}
 @Test void formalReleaseNeverCreatesOrderOrChangesFormalAvailability(){var c=review("RELEASE");restore(c);var r=reviews.submit(manager,c.intent(),body(c));assertEquals("RESOLVED",r.state());assertEquals("RELEASED",r.resolution());assertEquals(0,db.queryForObject("SELECT count(*) FROM ticket_order WHERE ticket_id=?",Integer.class,c.ticket()));assertEquals(4,ledger.snapshot(c.ticket(),1).snapshot().available());}
 @Test void corruptResultAuditedBlockedAndDoesNotResetReview(){var c=review("ABANDON");String before=job(c);var b=body(c);var r=reviews.submit(manager,c.intent(),b);assertEquals("BLOCKED",r.state());assertEquals("REDIS_CORRUPT",r.failure());assertEquals(2,audits(r.requestId()));restore(c);assertEquals("BLOCKED",reviews.submit(manager,c.intent(),b).state());assertEquals(before,job(c));assertEquals("RESOLVED",reviews.submit(manager,c.intent(),body(c)).state());}
 @Test void oppositeReceiptRemainsBlocked(){var c=review("ABANDON");restore(c);String field="r:"+c.intent();assertTrue(redis.opsForHash().hasKey(ledger.key(c.ticket(),1),field));String receipt=(String)redis.opsForHash().get(ledger.key(c.ticket(),1),field);redis.opsForHash().put(ledger.key(c.ticket(),1),field,receipt.replace("HELD","COMMITTED"));var r=reviews.submit(manager,c.intent(),body(c));assertEquals("BLOCKED",r.state());assertEquals("ABORTING",holds.inspect(c.intent()).state());assertEquals(1,db.queryForObject("SELECT attempts FROM stock_recovery_job WHERE intent_id=? AND kind=?",Integer.class,c.intent(),c.kind()));}
 @Test void originalReplayIsPgOnlyAfterNewEpoch(){var c=review("ABANDON");restore(c);var b=body(c);var r=reviews.submit(manager,c.intent(),b);var m=maintenance.submit(manager,c.ticket(),new StockMaintenanceService.Begin(UUID.randomUUID(),1));assertEquals("READY",m.state());assertEquals(2,m.generation());ownKeys.add(ledger.key(c.ticket(),2));redis.delete(ledger.key(c.ticket(),1));redis.delete(ledger.key(c.ticket(),2));assertEquals(r,reviews.submit(manager,c.intent(),b));assertEquals(2,audits(r.requestId()));assertEquals(2,projections.inspect(c.ticket()).generation());}
 @Test void actorScopeAndChangedBodyCannotAdoptOriginal(){var c=review("ABANDON");restore(c);var b=body(c);reviews.submit(manager,c.intent(),b);problem("REQUEST_CONFLICT",()->reviews.submit(other("MANAGER"),c.intent(),b));problem("REQUEST_CONFLICT",()->reviews.submit(manager,UUID.randomUUID(),b));problem("REQUEST_CONFLICT",()->reviews.submit(manager,c.intent(),new StockReviewService.Begin(b.requestId(),b.kind(),2,b.expectedDecision())));problem("NOT_FOUND",()->reviews.progress(other("MANAGER"),b.requestId()));}
 @Test void viewerReadsSettingsButCannotWriteOrReadOtherOperation(){String v=other("VIEWER");assertTrue(reviews.settings(v).enabled());var c=review("ABANDON");problem("FORBIDDEN",()->reviews.submit(v,c.intent(),body(c)));problem("NOT_FOUND",()->reviews.progress(v,UUID.randomUUID()));}
 @Test void flagOffCreatesNoFreshCommandButReplaysOwnedTerminal(){var c=review("ABANDON");restore(c);var b=body(c);var r=reviews.submit(manager,c.intent(),b);var off=new StockReviewService(db,holds,settlement,transactions,false);assertEquals(r,off.submit(manager,c.intent(),b));problem("REVIEW_DISABLED",()->off.submit(manager,c.intent(),body(c)));assertFalse(off.settings(manager).enabled());}
 @Test void wrongAttemptOrDecisionRejectedBeforeRegistration(){var c=review("COMMIT");problem("REVIEW_CHANGED",()->reviews.submit(manager,c.intent(),new StockReviewService.Begin(UUID.randomUUID(),c.kind(),2,c.target())));problem("REVIEW_CHANGED",()->reviews.submit(manager,c.intent(),new StockReviewService.Begin(UUID.randomUUID(),c.kind(),1,"RELEASE")));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_review_command WHERE intent_id=?",Integer.class,c.intent()));}
 @Test void waitingJobIsNotReviewAndMissingReadsHaveNoWrites(){UUID t=ticket();var user=customers.register("w-"+UUID.randomUUID(),"合成",UUID.randomUUID().toString());var h=holds.prepare(customers.authenticate(user.token()).orElseThrow(),new Place(UUID.randomUUID(),t,1,1,1200));problem("REVIEW_CHANGED",()->reviews.submit(manager,h.id(),new StockReviewService.Begin(UUID.randomUUID(),"UNUSED",1,"ABANDON")));problem("NOT_FOUND",()->reviews.progress(manager,UUID.randomUUID()));problem("INVALID_INPUT",()->reviews.audit(manager,UUID.randomUUID(),1,21));}
 @Test void sixConcurrentOriginalOperationsCommitOneResolutionAndAudit()throws Exception{var c=review("ABANDON");restore(c);var b=body(c);try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<StockReviewService.Receipt>>();for(int n=0;n<6;n++)jobs.add(()->reviews.submit(manager,c.intent(),b));for(var f:pool.invokeAll(jobs))assertEquals("RESOLVED",f.get().state());}assertEquals(2,audits(b.requestId()));assertEquals(4,ledger.snapshot(c.ticket(),1).snapshot().available());}
 @Test void luaReleaseBeforeAuditRollbackResumesSameUnusedCommand(){var c=review("ABANDON");restore(c);var b=body(c);db.execute("ALTER TABLE stock_review_audit ADD CONSTRAINT review_unused_fault CHECK(request_id<>'"+b.requestId()+"'::uuid OR state<>'RESOLVED') NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->reviews.submit(manager,c.intent(),b));assertEquals("REGISTERED",reviews.progress(manager,b.requestId()).state());assertEquals("ABORTING",holds.inspect(c.intent()).state());assertEquals(4,ledger.snapshot(c.ticket(),1).snapshot().available());assertEquals(1,audits(b.requestId()));}finally{db.execute("ALTER TABLE stock_review_audit DROP CONSTRAINT review_unused_fault");}assertEquals("RESOLVED",reviews.submit(manager,c.intent(),b).state());assertEquals(4,ledger.snapshot(c.ticket(),1).snapshot().available());assertEquals(2,audits(b.requestId()));}
 @Test void luaCommitBeforeAckAuditRollbackResumesOriginalFormalDecision(){var c=review("COMMIT");restore(c);var b=body(c);db.execute("ALTER TABLE stock_review_audit ADD CONSTRAINT review_commit_fault CHECK(request_id<>'"+b.requestId()+"'::uuid OR state<>'RESOLVED') NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->reviews.submit(manager,c.intent(),b));assertEquals("PENDING",reviews.progress(manager,b.requestId()).state());assertEquals(2,audits(b.requestId()));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_ack WHERE intent_id=?",Integer.class,c.intent()));assertEquals(1,ledger.snapshot(c.ticket(),1).snapshot().committed());}finally{db.execute("ALTER TABLE stock_review_audit DROP CONSTRAINT review_commit_fault");}assertEquals("RESOLVED",reviews.submit(manager,c.intent(),b).state());assertEquals(1,ledger.snapshot(c.ticket(),1).snapshot().committed());assertEquals(4,audits(b.requestId()));}
 @Test void downgradeBeforeResumePreservesOriginalAndCannotMutate(){var c=review("ABANDON");restore(c);var b=body(c);db.execute("ALTER TABLE stock_review_audit ADD CONSTRAINT review_role_fault CHECK(request_id<>'"+b.requestId()+"'::uuid OR state<>'RESOLVED') NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->reviews.submit(manager,c.intent(),b));db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);assertFalse(reviews.progress(manager,b.requestId()).canResume());problem("FORBIDDEN",()->reviews.submit(manager,c.intent(),b));assertEquals(1,audits(b.requestId()));}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);db.execute("ALTER TABLE stock_review_audit DROP CONSTRAINT review_role_fault");}assertEquals("RESOLVED",reviews.submit(manager,c.intent(),b).state());}
 @Test void freshResolvedReviewCannotBeReusedAsNewWork(){var c=review("ABANDON");restore(c);reviews.submit(manager,c.intent(),body(c));problem("REVIEW_CHANGED",()->reviews.submit(manager,c.intent(),body(c)));}
 @Test void sqlImmutableCommandAuditAndTerminalProofGuards(){var c=review("ABANDON");restore(c);var r=reviews.submit(manager,c.intent(),body(c));for(String sql:List.of("UPDATE stock_review_command SET expected_attempt=2 WHERE request_id=?","DELETE FROM stock_review_audit WHERE request_id=?","UPDATE stock_review_progress SET version=version+1 WHERE request_id=?")){var e=assertThrows(org.springframework.dao.DataAccessException.class,()->db.update(sql,r.requestId()));assertEquals("P0001",((java.sql.SQLException)e.getMostSpecificCause()).getSQLState());}assertEquals(2,audits(r.requestId()));}
 @Test void generationConflictIsBlockedBeforeRedisMutation(){var c=review("ABANDON");restore(c);UUID later=UUID.randomUUID();db.update("INSERT INTO stock_rebuild_command(request_id,ticket_id,generation,source_revision,available) VALUES(?,?,2,1,4)",later,c.ticket());db.update("UPDATE stock_projection SET generation=2,rebuild_request_id=? WHERE ticket_id=?",later,c.ticket());var r=reviews.submit(manager,c.intent(),body(c));assertEquals("BLOCKED",r.state());assertEquals("GENERATION_FENCED",r.failure());assertEquals(3,ledger.snapshot(c.ticket(),1).snapshot().available());assertEquals("ABORTING",holds.inspect(c.intent()).state());}
 @Test void keyMissingUsesExistingDomainEvidenceWithoutInitialization(){var c=review("COMMIT");redis.delete(ledger.key(c.ticket(),1));var r=reviews.submit(manager,c.intent(),body(c));assertEquals("RESOLVED",r.state());assertEquals("KEY_MISSING",r.resolution());assertFalse(redis.hasKey(ledger.key(c.ticket(),1)));assertEquals(1,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,c.ticket()));}
 @Test void outerTransactionAndInvalidBodyAreRejected(){var c=review("ABANDON");new TransactionTemplate(transactions).execute(tx->{assertThrows(IllegalStateException.class,()->reviews.submit(manager,c.intent(),body(c)));return null;});problem("INVALID_INPUT",()->reviews.submit(manager,c.intent(),new StockReviewService.Begin(UUID.randomUUID(),"UNUSED",0,"ABANDON")));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_review_command WHERE intent_id=?",Integer.class,c.intent()));}
}
